import collections

def transform(grid):
    # Determine the background color (most frequent value)
    counts = collections.Counter()
    for row in grid:
        counts.update(row)
    bg_color = counts.most_common(1)[0][0] if counts else 0

    R, C = len(grid), len(grid[0])

    best_rect = None # (r1, r2, c1, c2, color)
    max_area = 0

    # Iterate over all possible top-left corners to find the largest solid rectangle
    # of a color that is NOT the background color.
    for r1 in range(R):
        for c1 in range(C):
            val = grid[r1][c1]
            # Skip background color candidates
            if val == bg_color:
                continue

            # Try to find the largest rectangle starting at (r1, c1) of color 'val'
            for r2 in range(r1, R):
                for c2 in range(c1, C):
                    # Check if subgrid is solid 'val'
                    solid = True
                    for i in range(r1, r2 + 1):
                        for j in range(c1, c2 + 1):
                            if grid[i][j] != val:
                                solid = False
                                break
                        if not solid:
                            break

                    if solid:
                        area = (r2 - r1 + 1) * (c2 - c1 + 1)
                        if area > max_area:
                            max_area = area
                            best_rect = (r1, r2, c1, c2, val)

    # Construct output grid filled with background color
    out_grid = [[bg_color for _ in range(C)] for _ in range(R)]

    # Fill the found rectangle with its original color
    if best_rect:
        r1, r2, c1, c2, color = best_rect
        for i in range(r1, r2 + 1):
            for j in range(c1, c2 + 1):
                out_grid[i][j] = color

    return out_grid
